exercise.solution:
CREATE TABLE lab_l10_publishers (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_l10_magazines (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  publisher_id INTEGER NOT NULL REFERENCES lab_l10_publishers(id)
);

INSERT INTO lab_l10_publishers (id, name) VALUES (1, 'Acme'), (2, 'Globex');
INSERT INTO lab_l10_magazines (title, publisher_id) VALUES
  ('Monthly Review', 1), ('Data Weekly', 1), ('Outdoor Life', 2);

SELECT m.title, p.name AS publisher
FROM lab_l10_magazines m
JOIN lab_l10_publishers p ON p.id = m.publisher_id
ORDER BY m.title;

